const unarchiveSession = `-- name: UnarchiveSession :exec
UPDATE sessions SET archived_at = NULL
WHERE id = ?1 AND bot_id = ?2 AND channel_key NOT LIKE 'retired-telegram:%' AND (channel_key LIKE 'chat:%' OR parent_id IS NOT NULL)
`

type UnarchiveSessionParams struct {
	ID    int64  `json:"id"`
	BotID string `json:"bot_id"`
}

func (q *Queries) UnarchiveSession(ctx context.Context, arg UnarchiveSessionParams) error {
	_, err := q.db.ExecContext(ctx, unarchiveSession, arg.ID, arg.BotID)
	return err
}

const updateAutomation = `-- name: UpdateAutomation :execrows
UPDATE automations SET
    cwd = ?, name = ?, prompt = ?, schedule = ?, time_zone = ?, session = ?, enabled = ?, next_due_at = ?,
    notification_route = ?, notification_target_id = ?, runner_id = ?, updated_at = ?, target_session_id = ?
WHERE id = ? AND bot_id = ?
`

type UpdateAutomationParams struct {
	Cwd                  string         `json:"cwd"`
	Name                 string         `json:"name"`
	Prompt               string         `json:"prompt"`
	Schedule             string         `json:"schedule"`
	TimeZone             string         `json:"time_zone"`
	Session              string         `json:"session"`
	Enabled              int64          `json:"enabled"`
	NextDueAt            sql.NullInt64  `json:"next_due_at"`
	NotificationRoute    string         `json:"notification_route"`
	NotificationTargetID sql.NullString `json:"notification_target_id"`
	RunnerID             string         `json:"runner_id"`
	UpdatedAt            int64          `json:"updated_at"`
	TargetSessionID      sql.NullInt64  `json:"target_session_id"`
	ID                   string         `json:"id"`
	BotID                string         `json:"bot_id"`
}

func (q *Queries) UpdateAutomation(ctx context.Context, arg UpdateAutomationParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateAutomation,
		arg.Cwd,
		arg.Name,
		arg.Prompt,
		arg.Schedule,
		arg.TimeZone,
		arg.Session,
		arg.Enabled,
		arg.NextDueAt,
		arg.NotificationRoute,
		arg.NotificationTargetID,
		arg.RunnerID,
		arg.UpdatedAt,
		arg.TargetSessionID,
		arg.ID,
		arg.BotID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const updateBotSettings = `-- name: UpdateBotSettings :exec
UPDATE bots SET
    name = ?1,
    model_provider = ?2,
    model_id = ?3,
    thinking_level = ?4,
    fallback_provider = ?5,
    fallback_model_id = ?6,
    instructions = ?7,
    runner_sandbox_id = CASE WHEN runner_id = ?8 THEN runner_sandbox_id ELSE '' END,
    runner_id = ?8
WHERE id = ?9
`

type UpdateBotSettingsParams struct {
	Name             string `json:"name"`
	ModelProvider    string `json:"model_provider"`
	ModelID          string `json:"model_id"`
	ThinkingLevel    string `json:"thinking_level"`
	FallbackProvider string `json:"fallback_provider"`
	FallbackModelID  string `json:"fallback_model_id"`
	Instructions     string `json:"instructions"`
	RunnerID         string `json:"runner_id"`
	ID               string `json:"id"`
}

func (q *Queries) UpdateBotSettings(ctx context.Context, arg UpdateBotSettingsParams) error {
	_, err := q.db.ExecContext(ctx, updateBotSettings,
		arg.Name,
		arg.ModelProvider,
		arg.ModelID,
		arg.ThinkingLevel,
		arg.FallbackProvider,
		arg.FallbackModelID,
		arg.Instructions,
		arg.RunnerID,
		arg.ID,
	)
	return err
}

const upsertProvider = `-- name: UpsertProvider :exec
INSERT INTO providers (id, name, api, base_url, api_key, models, created_at)
VALUES (?, ?, ?, ?, ?, ?, ?)
ON CONFLICT (id) DO UPDATE SET
    name = excluded.name,
    api = excluded.api,
    base_url = excluded.base_url,
    api_key = excluded.api_key,
    models = excluded.models
`

type UpsertProviderParams struct {
	ID        string `json:"id"`
	Name      string `json:"name"`
	Api       string `json:"api"`
	BaseUrl   string `json:"base_url"`
	ApiKey    string `json:"api_key"`
	Models    string `json:"models"`
	CreatedAt int64  `json:"created_at"`
}

func (q *Queries) UpsertProvider(ctx context.Context, arg UpsertProviderParams) error {
	_, err := q.db.ExecContext(ctx, upsertProvider,
		arg.ID,
		arg.Name,
		arg.Api,
		arg.BaseUrl,
		arg.ApiKey,
		arg.Models,
		arg.CreatedAt,
	)
	return err
}

const withdrawSubmission = `-- name: WithdrawSubmission :execrows
UPDATE submissions SET status = 'unanswered', answer = NULL, reason = 'withdrawn',
    settled_at = coalesce(settled_at, ?1)
WHERE id = ?2 AND kind IN ('message', 'session_result', 'wake')
AND (status = 'pending' OR (status = 'unanswered' AND reason = 'aborted'))
`

type WithdrawSubmissionParams struct {
	Now sql.NullInt64 `json:"now"`
	ID  string        `json:"id"`
}

// A user withdraws one queued input. The settle worker can record the native abort first, so
// that reason also qualifies. The receipt and its source key stay, so a redelivery does not run
// the input. A withdrawn input has no reply to deliver to a channel.
func (q *Queries) WithdrawSubmission(ctx context.Context, arg WithdrawSubmissionParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, withdrawSubmission, arg.Now, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
